<?= $this->extend('layouts/management') ?>
<?= $this->section('subtitle') ?><p>Perbarui jumlah unit dan pantau produk yang perlu diisi ulang.</p><?= $this->endSection() ?>
<?= $this->section('content') ?><div class="stock-tabs"><?php foreach ([''=>['Semua stok',$stats['total']],'low'=>['Stok rendah',$stats['low']],'empty'=>['Stok habis',$stats['empty_stock']]] as $key=>[$label,$count]): ?><a href="<?= site_url('admin/inventory') . ($key ? '?stok=' . $key : '') ?>" <?= $filter === $key ? 'aria-current="page"' : '' ?>><?= $label ?> <span><?= (int) $count ?></span></a><?php endforeach ?></div>
<section class="surface"><header class="section-top"><div><h2>Stok produk</h2><p>Rendah berarti 1–<?= \App\Models\ProductModel::LOW_STOCK ?> unit. Stok habis berarti 0 unit.</p></div></header><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Kategori</th><th>Stok</th><th>Kondisi</th><th>Ubah jumlah</th></tr></thead><tbody>
<?php foreach ($products as $p): $n=(int) $p['stock']; ?><tr><td><div class="product-cell"><img class="thumb" src="<?= esc(pm_cover($p['cover']), 'attr') ?>" alt=""><a class="product-name" href="<?= site_url('admin/products/' . $p['id_product']) ?>"><?= esc($p['name']) ?></a></div></td><td><?= esc($p['category_name']) ?></td><td><?= $n ?></td><td><span class="tag <?= $n === 0 ? 'empty' : (pm_quantity($n) === 'Rendah' ? 'low' : 'good') ?>"><?= pm_quantity($n) ?></span></td><td><form class="stock-form" method="post" action="<?= site_url('admin/inventory/' . $p['id_product']) ?>"><?= csrf_field() ?><input type="hidden" name="previous" value="<?= $n ?>"><input type="hidden" name="stok" value="<?= esc($filter,'attr') ?>"><input type="number" name="stock" min="0" max="2147483647" step="1" required value="<?= $n ?>" aria-label="Stok <?= esc($p['name'], 'attr') ?>"><button class="pm-btn secondary">Simpan</button></form></td></tr><?php endforeach ?>
<?php if (!$products): ?><tr><td colspan="5" class="empty-result">Tidak ada produk pada kelompok stok ini.</td></tr><?php endif ?></tbody></table></div></section><?= $this->endSection() ?>
